Method.Source:
public void insertInvoiceDetailsInformation(CustInvoiceJour _custInvoiceJour,
    CustInvoiceTrans _custInvoiceTrans,
    CustPaymSchedLine _custPaymSchedLine,
    CustTrans _prepaymentCustTrans,
    TaxTrans _prepaymentTaxTrans)
{
    next insertInvoiceDetailsInformation(
        _custInvoiceJour, 
        _custInvoiceTrans, 
        _custPaymSchedLine, 
        _prepaymentCustTrans, 
        _prepaymentTaxTrans);
}

    public void generateInvoiceRelatedInformation(CustInvoiceJour _custInvoiceJour)
    {
        next generateInvoiceRelatedInformation(_custInvoiceJour);

        // Add entries for subs (functionality to be determined).
        this.metAddSubstituteInformation(_custInvoiceJour);
        this.metAddTotalsSection(_custInvoiceJour);

    }

    private void metAddTotalsSection(CustInvoiceJour _custInvoiceJour)
    {
        // Place holder, tbd rebates.
        // Pending requirements.

        Amount totalAmount;

        void add(str _desc, Amount _amount)
        {
            salesInvoiceTmp.METIsTotalLine              = true;
            salesInvoiceTmp.METTotalLineDescription     = _desc;
            salesInvoiceTmp.METTotalLineAmount          = _amount;
            salesInvoiceTmp.insert();

            totalAmount += _amount;
        }

        add('Sub total',                    _custInvoiceJour.SalesBalance);
        add('Distribution rebate 0.4%',     _custInvoiceJour.SalesBalance * 0.04);
        add('Total',                        totalAmount);
    }

    protected void populateSalesInvoiceHeaderFooterTmp(
        CustInvoiceJour _custInvoiceJour, 
        CompanyInfo _companyInfo)
    {
        next populateSalesInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);

        CustParameters      custParams          = CustParameters::find();
        CustTable           custTable           = _custInvoiceJour.custTable_OrderAccount();
        METCustTable        metCustTable        = METCustTable::find(custTable.AccountNum);
        BankAccountTable    eftBankAccount      = BankAccountTable::find(custFormLetterParameters.METInvoiceEFTBankAccountID);
        SalesTable          salesTable          = _custInvoiceJour.salesTable();
        CompanyInfo         companyInfo         = CompanyInfo::find();

        if(!eftBankAccount)
        {
            eftBankAccount = BankAccountTable::find(companyInfo.Bank);
        }

        salesInvoiceHeaderFooterTmp.METInvoiceReportInternetBankingNotes = custFormLetterParameters.METInvoiceReportInternetBankingNotes;
        salesInvoiceHeaderFooterTmp.METEFTAccountDetails    = strFmt('BSB: %1 A/C: %2', eftBankAccount.BankSortCode, eftBankAccount.AccountNum);
        salesInvoiceHeaderFooterTmp.METEFTReferenceText     = 'Payment reference: 999999';
        salesInvoiceHeaderFooterTmp.METStatementDate        = salesInvoiceHeaderFooterTmp.InvoiceDate;
        salesInvoiceHeaderFooterTmp.METBPayBillerCode       = metCustTable.BPayBillerCode;
        salesInvoiceHeaderFooterTmp.METBPayReference        = metCustTable.BPayReference;
        salesInvoiceHeaderFooterTmp.METDeliveryFee          = 9.9;
        salesInvoiceHeaderFooterTmp.METAdminFee             = 9.9;
        salesInvoiceHeaderFooterTmp.METDeliveryRoute        = '999 / 999';
        salesInvoiceHeaderFooterTmp.METCustGroup            = custTable.CustGroup;
        salesInvoiceHeaderFooterTmp.METTobaccoLicense       = '99999';
        salesInvoiceHeaderFooterTmp.METLiquorLicense        = '99999';
        salesInvoiceHeaderFooterTmp.METRepCode              = salesTable.SalesGroup;
        salesInvoiceHeaderFooterTmp.METBPayMessage          = custFormLetterParameters.METBpayMessageToCustomer;

    }

    protected void populateSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour,
        CustInvoiceTrans _custInvoiceTrans,
        TaxSpec _taxSpec,
        CustPaymSchedLine _custPaymSchedLine,
        CustTrans _prepaymentCustTrans,
        TaxTrans _prepaymentTaxTrans)
    {
        next populateSalesInvoiceTmp(
            _custInvoiceJour, 
            _custInvoiceTrans, 
            _taxSpec, 
            _custPaymSchedLine, 
            _prepaymentCustTrans, 
            _prepaymentTaxTrans);

        salesInvoiceTmp.METSalesInvoiceReportLineType   = METSalesInvoiceReportLineType::Line;
        salesInvoiceTmp.METAlcoholCategory              = '???';
        salesInvoiceTmp.METAlcLitres                    = 99;
        salesInvoiceTmp.METRetailAmount                 = salesInvoiceTmp.LineAmount + 0.50;    // ****
        salesInvoiceTmp.METDeliveryFee                  = 99.99;
        salesInvoiceTmp.METCaseCost                     = salesInvoiceTmp.SalesPrice * 2;
        salesInvoiceTmp.METWET                          = 'Y';  // **
        salesInvoiceTmp.METGST                          = salesInvoiceTmp.TaxAmount ? 'Y' : 'N';
        salesInvoiceTmp.METPackQty                      = _custInvoiceTrans.QtyPhysical;
    }
